Panel.
References',45,'Structure Bookmarks','regulation','US','2021-11-15','public_domain','[]','[]');
INSERT OR REPLACE INTO chunks (id,document_id,chunk_index,content,page,section,layer,jurisdiction,doc_date,license,material_tags,package_tags) VALUES ('epa-national-recycling-strategy::0052','epa-national-recycling-strategy',52,'38
National Recycling Strategy
November 15, 2021
 
●
