INSERT OR REPLACE INTO chunks (id,document_id,chunk_index,content,page,section,layer,jurisdiction,doc_date,license,material_tags,package_tags) VALUES ('me-epr-dep::0000','me-epr-dep',0,'**Alternative Collection Programs** \*\*coming soon

