INSERT OR REPLACE INTO chunks (id,document_id,chunk_index,content,page,section,layer,jurisdiction,doc_date,license,material_tags,package_tags) VALUES ('co-hb22-1355::0008','co-hb22-1355',8,'(B) NOT DESIGNED FOR REUSE OR REFILL. 
