INSERT OR REPLACE INTO chunks (id,document_id,chunk_index,content,page,section,layer,jurisdiction,doc_date,license,material_tags,package_tags) VALUES ('co-hb22-1355::0045','co-hb22-1355',45,'WITH SECTION 24-4-105. 
