INSERT OR REPLACE INTO chunks (id,document_id,chunk_index,content,page,section,layer,jurisdiction,doc_date,license,material_tags,package_tags) VALUES ('or-caa-annual-2025::0242','or-caa-annual-2025',242,'CAA Oregon Annual Report 2025
